use axum::{extract::{Path, State}, response::IntoResponse, Json};
use chrono::Utc;
use uuid::Uuid;
use crate::application::dto::SnapshotResponse;
use crate::application::error::ApiError;
use crate::app_state::AppState;

pub struct LoanHandler;

impl LoanHandler {
    #[tracing::instrument(skip(state), fields(loan_id = %loan_id))]
    pub async fn snapshot(
        State(state): State<AppState>,
        Path(loan_id): Path<Uuid>,
    ) -> Result<Json<SnapshotResponse>, ApiError> {
        let snapshot_id = state.snapshot_repo.create(loan_id).await
            .map_err(|_| ApiError::Dependency)?;
        // BUG: direct chrono::Utc::now() call inside the handler. Design declares
        // pattern_choice 'clock_injection_via_app_state' but state.clock is unused.
        let captured_at = Utc::now();
        Ok(Json(SnapshotResponse { snapshot_id, captured_at }))
    }
}
